package com.android.sharemate.model.item

import java.time.LocalDate
import java.time.ZoneOffset
import java.util.Date


/**
 * Represents a food item or a receipt in the application.
 *
 * @property id Unique identifier of the item (generated by Firestore).
 * @property name Name of the food item (e.g., "Milk").
 * @property ownerId The Firebase UID of the user who created the item.
 * @property householdId The household ID if the item is shared. If null, the item is strictly private.
 * @property expirationDate Expiration date of the food item.
 * @property category Category of the food item.
 */
data class Item(
    val id: String = "",
    val name: String = "",
    val ownerId: String = "",
    val householdId: String? = null,
    val expirationDate: Date? = null,
    val category: String? = null,
) {
  /** Helper to easily determine if an item is shared or private in the UI. */
  val isShared: Boolean
    get() = householdId != null
}

/**
 * Extension function to convert a Date into a LocalDate by forcing the UTC timezone.
 * This prevents day shifts caused by time zones.
 */
fun Date.toLocalDateUtc(): LocalDate {
    return this.toInstant().atZone(ZoneOffset.UTC).toLocalDate()
}